//! Associative recipes (SPEC §6.2.1, #166, ADR 0011): geometry derived from
//! other geometry that updates with it. A [`Recipe`] stores a kind, the source
//! entity IDs and the IDs of the instance entities it generated. Instances are
//! ordinary entities in the store (so constraints and dimensions can refer to
//! them) but are *driven*: they can't be dragged, edited or deleted, only
//! regenerated by the recipe, exploded into plain geometry, or removed with it.
//!
//! # ID policy (ADR 0003)
//! Instance IDs come from the document's normal allocator the first time an
//! instance is created, and the recipe keeps them in [`Recipe::pool`] ever
//! after: if instances are later removed and re-created, or an undo brings
//! them back, they get *their own* IDs again. An ID is never handed to
//! anything else and the counter never goes back.

use crate::document::Document;
use crate::entity::{EntityKind, Geom};
use crate::error::DocError;
use crate::ids::{ConstraintId, EntityId, RecipeId};
use locus_geom::Vec2;
use serde::{Deserialize, Serialize};
use std::collections::BTreeSet;

/// Default instance limit (SPEC §6.2.1): copies of the source geometry one
/// recipe may hold.
pub const MAX_INSTANCES: usize = 10_000;

/// Upper bound on the entities one recipe generates (instances × entities
/// per instance), so a hostile file or a big source can't exhaust memory.
pub const MAX_INSTANCE_ENTITIES: usize = 200_000;

/// What a recipe does, with its parameters.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum RecipeKind {
    /// Mirror the sources about a line (SPEC §6.2.1). The copies are solved
    /// with the sketch: `Symmetric` constraints tie every copied point to its
    /// source, so editing the source moves the copy.
    Mirror { axis: EntityId },
    /// Offset a chain of curves (SPEC §6.2, #164): `distance` > 0 grows a
    /// closed chain / goes left of an open one. `expr`, when set, is
    /// evaluated with the document's parameters instead. `sharp` keeps
    /// corners sharp (mitred) instead of round. Not solved: the instances are
    /// regenerated from the solved sources (see `crate::offset`).
    Offset {
        distance: f64,
        sharp: bool,
        #[serde(default)]
        expr: Option<String>,
    },
}

impl RecipeKind {
    /// Whether the instances take part in the solve (mirror: yes, through its
    /// owned constraints) or are only written after it from the sources.
    #[must_use]
    pub fn solved(&self) -> bool {
        match self {
            Self::Mirror { .. } => true,
            Self::Offset { .. } => false,
        }
    }

    /// How many copies of the source geometry the recipe currently makes.
    #[must_use]
    pub fn instance_count(&self) -> usize {
        match self {
            Self::Mirror { .. } | Self::Offset { .. } => 1,
        }
    }

    /// Entities the recipe reads besides its sources (e.g. the mirror axis).
    #[must_use]
    pub fn references(&self) -> Vec<EntityId> {
        match self {
            Self::Mirror { axis } => vec![*axis],
            Self::Offset { .. } => Vec::new(),
        }
    }

    pub(crate) fn name(&self) -> &'static str {
        match self {
            Self::Mirror { .. } => "Mirror",
            Self::Offset { .. } => "Offset",
        }
    }
}

/// A stored recipe.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Recipe {
    pub kind: RecipeKind,
    /// The entities the user picked, sorted and unique. The points they are
    /// built from are copied too (see [`closure`]).
    pub sources: Vec<EntityId>,
    /// `pool[k][i]` is the entity ID of copy `k` of `closure(sources)[i]`.
    /// Every ID ever allocated to the recipe, including those of copies that
    /// currently don't exist (ID policy above).
    pub pool: Vec<Vec<EntityId>>,
    /// How many leading copies of `pool` exist as entities right now.
    pub active: usize,
    /// Constraints the recipe created and owns (mirror's `Symmetric` ties).
    #[serde(default)]
    pub constraints: Vec<ConstraintId>,
}

impl Recipe {
    /// The entity IDs of the copies that currently exist. A non-solved
    /// offset keeps one flat list in `pool[0]`, of which the first `active`
    /// exist (`crate::offset`).
    pub fn instances(&self) -> impl Iterator<Item = EntityId> + '_ {
        let flat = self.is_flat();
        let (copies, per) = if flat {
            (1, self.active)
        } else {
            (self.active, usize::MAX)
        };
        self.pool
            .iter()
            .take(copies)
            .flat_map(move |set| set.iter().take(per))
            .copied()
    }

    /// Whether `pool[0]` is a flat ID list (offsets) rather than one set of
    /// IDs per copy of the sources' closure (mirror, patterns).
    #[must_use]
    pub fn is_flat(&self) -> bool {
        matches!(self.kind, RecipeKind::Offset { .. })
    }

    /// Every entity this recipe depends on: sources, their points and the
    /// kind's extras.
    #[must_use]
    pub fn inputs(&self, doc: &Document) -> BTreeSet<EntityId> {
        let mut s = closure(doc, &self.sources);
        s.extend(self.kind.references());
        s
    }
}

/// The sources plus the points they are built from, sorted by ID. Entities
/// that don't exist are skipped (validated elsewhere).
#[must_use]
pub fn closure(doc: &Document, sources: &[EntityId]) -> BTreeSet<EntityId> {
    let mut s = BTreeSet::new();
    for id in sources {
        if let Some(e) = doc.entity(*id) {
            s.insert(*id);
            s.extend(e.geom.point_refs());
        }
    }
    s
}

/// A rigid or reflecting map of the plane that generates one copy.
#[derive(Debug, Clone, Copy)]
pub(crate) enum Xf {
    Reflect { a: Vec2, b: Vec2 },
}

impl Xf {
    pub(crate) fn apply(self, p: Vec2) -> Vec2 {
        match self {
            Self::Reflect { a, b } => {
                // The caller has checked the axis isn't degenerate; if it
                // were, `normalized` would be None and p is left unchanged.
                let Some(d) = (b - a).normalized(0.0) else {
                    return p;
                };
                let v = p - a;
                a + d * (2.0 * v.dot(d)) - v
            }
        }
    }

    /// Reflections reverse orientation, so a counter-clockwise arc must swap
    /// its end points to stay counter-clockwise.
    pub(crate) fn flips(self) -> bool {
        match self {
            Self::Reflect { .. } => true,
        }
    }
}

/// The map for copy `k` of `kind`, from the document's current geometry.
pub(crate) fn transform(doc: &Document, kind: &RecipeKind, _k: usize) -> Result<Xf, DocError> {
    match kind {
        RecipeKind::Offset { .. } => Err(DocError::Invalid(
            "an offset is not a copy of its sources".to_owned(),
        )),
        RecipeKind::Mirror { axis } => {
            let line = doc.line(*axis).ok_or(DocError::UnknownEntity(*axis))?;
            if (line.b - line.a).length() <= f64::EPSILON {
                return Err(DocError::Invalid(
                    "the mirror line has zero length".to_owned(),
                ));
            }
            Ok(Xf::Reflect {
                a: line.a,
                b: line.b,
            })
        }
    }
}

/// The geometry of one copy of `src`, with point references renamed by `map`.
pub(crate) fn copy_geom(src: &Geom, xf: Xf, map: &impl Fn(EntityId) -> EntityId) -> Geom {
    match src {
        Geom::Point { pos } => Geom::Point {
            pos: xf.apply(*pos),
        },
        Geom::Line { start, end } => Geom::Line {
            start: map(*start),
            end: map(*end),
        },
        Geom::Circle { center, radius } => Geom::Circle {
            center: map(*center),
            radius: *radius,
        },
        Geom::Bezier {
            start,
            start_ctrl,
            end_ctrl,
            end,
        } => Geom::Bezier {
            start: map(*start),
            start_ctrl: map(*start_ctrl),
            end_ctrl: map(*end_ctrl),
            end: map(*end),
        },
        // The layout cache is in the text's local frame, so a copy only needs
        // its anchor/direction points re-pointed (a mirrored copy reads
        // correctly, not mirrored).
        Geom::Text { anchor, dir, text } => Geom::Text {
            anchor: map(*anchor),
            dir: map(*dir),
            text: text.clone(),
        },
        Geom::Arc { center, start, end } => {
            let (s, e) = if xf.flips() {
                (end, start)
            } else {
                (start, end)
            };
            Geom::Arc {
                center: map(*center),
                start: map(*s),
                end: map(*e),
            }
        }
    }
}

/// Structural checks shared by commands and file loading: the sources exist,
/// aren't themselves generated, the kind's parameters make sense, and the
/// limits hold.
///
/// `self_id` is the recipe being edited (its own instances may be sources'
/// neighbours), `None` for a new one.
pub(crate) fn validate(
    doc: &Document,
    kind: &RecipeKind,
    sources: &[EntityId],
    self_id: Option<RecipeId>,
) -> Result<(), DocError> {
    if sources.is_empty() {
        return Err(DocError::Invalid(
            "a recipe needs at least one source entity".to_owned(),
        ));
    }
    let driven = doc.driven_entities();
    for id in sources.iter().chain(&kind.references()) {
        doc.entity(*id).ok_or(DocError::UnknownEntity(*id))?;
        if let Some(r) = driven.get(id).filter(|r| Some(**r) != self_id) {
            return Err(DocError::Driven {
                entity: *id,
                recipe: *r,
            });
        }
    }
    let sorted: BTreeSet<_> = sources.iter().collect();
    if sorted.len() != sources.len() {
        return Err(DocError::Invalid("duplicate source entity".to_owned()));
    }
    match kind {
        RecipeKind::Mirror { axis } => {
            if doc.entity(*axis).map(|e| e.geom.kind()) != Some(EntityKind::Line) {
                return Err(DocError::WrongKind {
                    what: "mirror line",
                    entity: *axis,
                    expected: "line",
                    found: doc
                        .entity(*axis)
                        .map_or(EntityKind::Point, |e| e.geom.kind()),
                });
            }
            if sources.contains(axis) {
                return Err(DocError::SameEntity {
                    what: "mirror",
                    entity: *axis,
                });
            }
            transform(doc, kind, 0)?;
        }
        RecipeKind::Offset { distance, .. } => {
            if !distance.is_finite()
                || distance.abs() <= locus_geom::SOLVER_TOL
                || distance.abs() > crate::operation::MAX_LENGTH
            {
                return Err(DocError::Invalid(
                    "offset distance must be non-zero and at most 1000 mm".to_owned(),
                ));
            }
            crate::offset::chain(doc, sources)?;
        }
    }
    let per = closure(doc, sources).len();
    let n = kind.instance_count();
    if n > MAX_INSTANCES {
        return Err(DocError::InstanceLimit {
            requested: n,
            limit: MAX_INSTANCES,
        });
    }
    if n.saturating_mul(per) > MAX_INSTANCE_ENTITIES {
        return Err(DocError::InstanceLimit {
            requested: n.saturating_mul(per),
            limit: MAX_INSTANCE_ENTITIES,
        });
    }
    Ok(())
}

/// The active copies of `source` across all recipes: `(instance, recipe)`.
pub(crate) fn instances_of(doc: &Document, source: EntityId) -> Vec<(EntityId, RecipeId)> {
    let mut out = Vec::new();
    for (rid, r) in doc.recipes() {
        let cl: Vec<EntityId> = closure(doc, &r.sources).into_iter().collect();
        if r.is_flat() {
            continue;
        }
        if let Some(i) = cl.iter().position(|c| *c == source) {
            out.extend(
                r.pool
                    .iter()
                    .take(r.active)
                    .filter_map(|set| set.get(i))
                    .map(|e| (*e, *rid)),
            );
        }
    }
    out
}

/// Whole-document recipe consistency, for file loading: pool IDs are unique
/// and below the counter, active copies exist and inactive ones don't, and
/// every reference resolves. Never panics on a hostile file.
pub(crate) fn validate_all(doc: &Document) -> Result<(), DocError> {
    let mut seen = BTreeSet::new();
    for (rid, r) in doc.recipes() {
        let bad = |m: &str| DocError::Invalid(format!("recipe {rid}: {m}"));
        validate(doc, &r.kind, &r.sources, Some(*rid)).map_err(|e| bad(&e.to_string()))?;
        if (!r.is_flat() && r.active > r.pool.len()) || r.pool.len() > MAX_INSTANCES {
            return Err(bad("instance count out of range"));
        }
        let per = closure(doc, &r.sources).len();
        let flat = r.is_flat();
        if flat && (r.pool.len() > 1 || r.pool.first().map_or(0, Vec::len) < r.active) {
            return Err(bad("offset instance list out of range"));
        }
        for (k, set) in r.pool.iter().enumerate() {
            if !flat && set.len() != per {
                return Err(bad("instance set does not match the sources"));
            }
            for (i, id) in set.iter().enumerate() {
                if id.get() >= doc.next_id() || !seen.insert(*id) {
                    return Err(bad("instance ID reused or beyond the counter"));
                }
                let live = if flat { i < r.active } else { k < r.active };
                if live != doc.entity(*id).is_some() {
                    return Err(bad("instance entities do not match the active count"));
                }
            }
        }
        for c in &r.constraints {
            if doc.constraint(*c).is_none() {
                return Err(bad("owned constraint is missing"));
            }
        }
    }
    Ok(())
}
